package com.qrunio.platform.newsletter;
import java.sql.Timestamp; import java.time.*; import java.util.*; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class CampaignService {
 private final JdbcTemplate db; private final Clock clock; CampaignService(JdbcTemplate db,Clock clock){this.db=db;this.clock=clock;}
 @Transactional public int enqueue(UUID campaignId){Instant n=clock.instant();var campaign=db.queryForMap("select subject,content,segment_id from newsletter_campaign where id=? and status in ('scheduled','draft')",campaignId);UUID segment=(UUID)campaign.get("segment_id");String sql="select id,email from newsletter_subscription s where status='confirmed' and not exists(select 1 from email_suppression x where x.email=s.email and (x.expires_at is null or x.expires_at>?))";List<Subscriber> recipients=db.query(sql,(r,i)->new Subscriber(r.getObject(1,UUID.class),r.getString(2)),Timestamp.from(n));int count=0;for(var s:recipients){db.update("insert into outbound_email(id,subscription_id,campaign_id,message_type,recipient,subject,body,status,next_attempt_at,created_at) values(?,?,?,?,?,?,?,?,?,?)",UUID.randomUUID(),s.id,campaignId,"campaign",s.email,campaign.get("subject"),campaign.get("content"),"pending",Timestamp.from(n),Timestamp.from(n));count++;}db.update("update newsletter_campaign set status='sending',updated_at=? where id=?",Timestamp.from(n),campaignId);return count;}
 private record Subscriber(UUID id,String email){}
}
